public static class VoiceInstallCore {
 public static string HashFile(string file){using(var s=File.OpenRead(file))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 public static void Verify(string file,long bytes,string hash){if(!Regex.IsMatch(hash??"","^[a-f0-9]{64}$")||new FileInfo(file).Length!=bytes||HashFile(file)!=hash)throw new IOException("Контрольная сумма загрузки не совпала. Установка остановлена; повторите загрузку.");}
 public static void RemoveStaging(string directory){string versions=Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Akronikl","LocalVoice","versions"));string target=Path.GetFullPath(directory);if(!String.Equals(Path.GetDirectoryName(target),versions,StringComparison.OrdinalIgnoreCase)||!Regex.IsMatch(Path.GetFileName(target),"^\\.installing-[a-f0-9]{32}$"))throw new IOException("Недопустимая папка очистки.");if((File.GetAttributes(target)&FileAttributes.ReparsePoint)!=0||Directory.GetDirectories(target,"*",SearchOption.AllDirectories).Any(d=>(File.GetAttributes(d)&FileAttributes.ReparsePoint)!=0))throw new IOException("Найдена ссылка в папке установки; очистка остановлена.");Directory.Delete(target,true);}
 public static void Extract(string archive,string destination,long expectedBytes,Action<long> progress,bool applicationOverlay=false){Extract(archive,destination,expectedBytes,progress,applicationOverlay,CancellationToken.None);}
 public static void Extract(string archive,string destination,long expectedBytes,Action<long> progress,bool applicationOverlay,CancellationToken cancellation){
  string root=Path.GetFullPath(destination).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;long total=0;Directory.CreateDirectory(root);byte[] copyBuffer=new byte[1024*1024];
  using(var zip=ZipFile.OpenRead(archive))foreach(var e in zip.Entries){
   cancellation.ThrowIfCancellationRequested();
   if(e.FullName.IndexOf(':')>=0||e.FullName.IndexOf('\0')>=0||Path.IsPathRooted(e.FullName)||((e.ExternalAttributes>>16)&0xF000)==0xA000)throw new IOException("Недопустимый путь в пакете.");
   string name=Path.GetFullPath(Path.Combine(root,e.FullName.Replace('/',Path.DirectorySeparatorChar)));if(!name.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new IOException("Путь вне папки установки.");
   if(String.IsNullOrEmpty(e.Name)){Directory.CreateDirectory(name);continue;}total=checked(total+e.Length);if(total>expectedBytes)throw new IOException("Размер пакета превышен.");Directory.CreateDirectory(Path.GetDirectoryName(name));
   bool replace=applicationOverlay&&(new[]{"local-voice.mjs","local-speech-worker.py","qwen-greedy-predictor.py","uyut7-narrator.wav","Start.ps1","START.cmd","README_RU.txt","PACKAGE_MANIFEST.json","Uninstall.ps1","runtime/concrt140.dll","runtime/msvcp140.dll","runtime/msvcp140_1.dll","runtime/msvcp140_2.dll","runtime/msvcp140_atomic_wait.dll","runtime/msvcp140_codecvt_ids.dll","runtime/vccorlib140.dll","runtime/vcruntime140.dll","runtime/vcruntime140_1.dll","runtime/vcruntime140_threads.dll"}.Contains(e.FullName)||e.FullName.StartsWith("THIRD_PARTY_NOTICES/",StringComparison.Ordinal)||e.FullName.StartsWith("runtime/Lib/site-packages/sox/",StringComparison.Ordinal)||e.FullName.StartsWith("runtime/Lib/site-packages/sox-1.5.0.dist-info/",StringComparison.Ordinal));if(applicationOverlay&&!replace)throw new IOException("Недопустимый файл программы голоса.");
   using(var input=e.Open())using(var output=new FileStream(name,replace?FileMode.Create:FileMode.CreateNew,FileAccess.Write,FileShare.None)){int n;while((n=input.Read(copyBuffer,0,copyBuffer.Length))>0){cancellation.ThrowIfCancellationRequested();output.Write(copyBuffer,0,n);}}progress(total);
  }
  if(total!=expectedBytes)throw new IOException("Пакет распакован не полностью.");
 }
 public static string Gpu(){return GpuDevice().display;}
 public static VoiceGpu GpuDevice(){
  string[] locations={Path.Combine(Environment.SystemDirectory,"nvidia-smi.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"NVIDIA Corporation","NVSMI","nvidia-smi.exe")};string path=locations.FirstOrDefault(File.Exists)??"nvidia-smi.exe";
  var info=new ProcessStartInfo(path,"--query-gpu=uuid,name,memory.total,compute_cap,driver_version --format=csv,noheader,nounits"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};
  try{using(var p=Process.Start(info)){var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(8000)){p.Kill();throw new Exception();}if(p.ExitCode!=0)throw new Exception();string text=output.GetAwaiter().GetResult();foreach(string line in text.Split('\n')){var fields=line.Trim().Split(',').Select(x=>x.Trim()).ToArray();int memory;double capability;Version driver;if(fields.Length==5&&Regex.IsMatch(fields[0],"^GPU-[a-fA-F0-9-]+$")&&Int32.TryParse(fields[2],out memory)&&Double.TryParse(fields[3],System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out capability)&&Version.TryParse(fields[4],out driver)&&memory>=7680&&capability>=8&&driver.CompareTo(new Version(572,61))>=0)return new VoiceGpu{uuid=fields[0],display=fields[1]+" · "+memory+" МиБ"};}}}catch{}
  throw new InvalidOperationException("Для этого голоса нужен Windows x64 и NVIDIA с 8 ГБ видеопамяти, поддержкой BF16 и подходящим драйвером (572.61 или новее). На этом компьютере проверка не пройдена. Быстрый голос Piper доступен в Nexus без установки.");
 }
 public static async Task Download(VoiceArchive a,string file,Action<long> progress,CancellationToken ct){
  if(File.Exists(file)){try{await Task.Run(()=>Verify(file,a.bytes,a.sha256),ct);progress(a.bytes);return;}catch(IOException){File.Delete(file);}}string partial=file+".part";long offset=File.Exists(partial)?new FileInfo(partial).Length:0;if(offset>a.bytes)throw new IOException("Неверный размер незавершённой загрузки.");
  if(offset<a.bytes){using(var handler=new HttpClientHandler{AllowAutoRedirect=false})using(var client=new HttpClient(handler)){client.Timeout=Timeout.InfiniteTimeSpan;using(var request=new HttpRequestMessage(HttpMethod.Get,a.url)){
   if(offset>0)request.Headers.Range=new System.Net.Http.Headers.RangeHeaderValue(offset,null);
   using(var headersTimeout=CancellationTokenSource.CreateLinkedTokenSource(ct)){headersTimeout.CancelAfter(45000);using(var response=await client.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,headersTimeout.Token)){headersTimeout.CancelAfter(Timeout.Infinite);
    if(response.StatusCode==HttpStatusCode.OK)offset=0;else if(response.StatusCode!=HttpStatusCode.PartialContent||response.Content.Headers.ContentRange==null||response.Content.Headers.ContentRange.From!=offset||response.Content.Headers.ContentRange.Length!=a.bytes)throw new IOException("Сервер не подтвердил продолжение загрузки.");
    if(response.Content.Headers.ContentLength!=a.bytes-offset)throw new IOException("Сервер вернул неверный размер загрузки.");
    using(var input=await response.Content.ReadAsStreamAsync())using(var output=new FileStream(partial,FileMode.OpenOrCreate,FileAccess.Write,FileShare.None)){output.SetLength(offset);output.Position=offset;byte[] buffer=new byte[1024*1024];long done=offset;progress(done);
     while(true){ct.ThrowIfCancellationRequested();var read=input.ReadAsync(buffer,0,buffer.Length,ct);if(await Task.WhenAny(read,Task.Delay(45000,ct))!=read)throw new IOException("Соединение прервано. Нажмите установить ещё раз: загрузка продолжится.");int n=await read;if(n==0)break;done+=n;if(done>a.bytes)throw new IOException("Размер загрузки превышен.");await output.WriteAsync(buffer,0,n,ct);progress(done);}
    }
   }}
  }}}
  try{await Task.Run(()=>Verify(partial,a.bytes,a.sha256),ct);}catch(IOException){File.Delete(partial);throw;}File.Move(partial,file);
 }
 public static VoiceSetupConfig Config(){using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("setup-config.json"))using(var r=new StreamReader(stream,Encoding.UTF8)){var c=new JavaScriptSerializer().Deserialize<VoiceSetupConfig>(r.ReadToEnd());if(!Regex.IsMatch(c.version??"","^[a-z0-9.-]{8,80}$")||c.archives==null||c.archives.Length!=3||!c.archives.Select(a=>a.file).SequenceEqual(new[]{"runtime.zip","model.zip","application.zip"}))throw new IOException("Некорректный установщик.");foreach(var a in c.archives){var u=new Uri(a.url);if(u.Scheme!="https"||u.Host!="storage.yandexcloud.net"||!a.url.StartsWith(c.baseUrl,StringComparison.Ordinal)||!Regex.IsMatch(a.sha256??"","^[a-f0-9]{64}$")||a.bytes<=0||a.unpackedBytes<=0)throw new IOException("Некорректный пакет установки.");}return c;}}
 public static void Shortcut(string directory){
  string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Akronikl");Directory.CreateDirectory(folder);dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));dynamic link=shell.CreateShortcut(Path.Combine(folder,"Голос Уют-7 Qwen TTS.lnk"));link.TargetPath=Path.Combine(Environment.SystemDirectory,"WindowsPowerShell","v1.0","powershell.exe");link.Arguments="-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File \""+Path.Combine(directory,"Start.ps1")+"\"";link.WorkingDirectory=directory;link.Description="Локальный голос Уют-7 для Akronikl IT Nexus";link.Save();
 }
 public static void Launch(string directory){Process.Start(new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,"WindowsPowerShell","v1.0","powershell.exe"),"-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File \""+Path.Combine(directory,"Start.ps1")+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=directory});}
 public static void Register(string directory,string version){using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\AkroniklLocalQwenVoice")){key.SetValue("DisplayName","Голос Уют-7 · Qwen TTS для Nexus");key.SetValue("DisplayVersion",version);key.SetValue("Publisher","Akronikl IT Nexus");key.SetValue("InstallLocation",directory);key.SetValue("UninstallString","\""+Path.Combine(Environment.SystemDirectory,"WindowsPowerShell","v1.0","powershell.exe")+"\" -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File \""+Path.Combine(directory,"Uninstall.ps1")+"\"");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}using(var protocol=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\Classes\akronikl-nexus-voice")){protocol.SetValue("","URL:Akronikl Nexus local voice");protocol.SetValue("URL Protocol","");using(var command=protocol.CreateSubKey(@"shell\open\command"))command.SetValue("","\""+Path.Combine(Environment.SystemDirectory,"WindowsPowerShell","v1.0","powershell.exe")+"\" -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File \""+Path.Combine(directory,"Start.ps1")+"\"");}}
}
public sealed class VoiceSetupForm:Form {
 readonly VoiceSetupConfig config;readonly Label description=new Label(),status=new Label();readonly ProgressBar progress=new ProgressBar();readonly Button install=new Button(),cancel=new Button();CancellationTokenSource cancellation;bool busy=false,committed=false;
 public VoiceSetupForm(VoiceSetupConfig c){config=c;Text="Установка голоса «Уют-7» · Qwen TTS";Width=680;Height=430;MinimumSize=Size;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(12,25,41);ForeColor=Color.White;
  var title=new Label{Text="Живой голос «Уют-7» для Nexus",Left=24,Top=24,Width=610,Height=35,Font=new Font("Segoe UI",17,FontStyle.Bold)};Controls.Add(title);
  description.SetBounds(24,78,610,116);description.Text="Установщик сам загрузит модель, Python, Node и библиотеки.\r\nНичего искать отдельно и вводить API-ключ не нужно.\r\n\r\nЗагрузка: "+(c.archives.Sum(a=>a.bytes)/1073741824d).ToString("0.0")+" ГБ. После установки: "+(c.archives.Sum(a=>a.unpackedBytes)/1073741824d).ToString("0.0")+" ГБ.\r\nWindows x64 · NVIDIA с 8 ГБ видеопамяти. Для телефонов — Piper.";Controls.Add(description);
  progress.SetBounds(24,218,610,22);Controls.Add(progress);status.SetBounds(24,255,610,64);status.Text="Перед загрузкой проверим компьютер и свободное место.";Controls.Add(status);
  install.SetBounds(24,330,220,38);install.Text="Установить голос";install.ForeColor=Color.Black;install.Click+=async(s,e)=>await Install();Controls.Add(install);cancel.SetBounds(414,330,220,38);cancel.Text="Закрыть";cancel.ForeColor=Color.Black;cancel.Click+=(s,e)=>{if(busy&&!committed)cancellation.Cancel();else Close();};Controls.Add(cancel);
  FormClosing+=(s,e)=>{if(busy&&!committed){e.Cancel=true;cancellation.Cancel();}};
 }
 void Report(string text,int percent){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action(()=>Report(text,percent)));return;}status.Text=text;progress.Value=Math.Max(0,Math.Min(100,percent));}
 async Task Install(){if(busy)return;busy=true;committed=false;install.Enabled=false;cancel.Text="Остановить";cancellation=new CancellationTokenSource();string staging=null;
  try{
   if(!Environment.Is64BitOperatingSystem)throw new InvalidOperationException("Нужен Windows x64.");VoiceGpu device=await Task.Run(()=>VoiceInstallCore.GpuDevice());string gpu=device.display;
   string home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Akronikl","LocalVoice"),versions=Path.Combine(home,"versions"),target=Path.Combine(versions,config.version),cache=Path.Combine(home,"downloads");Directory.CreateDirectory(versions);Directory.CreateDirectory(cache);
   if(Directory.Exists(target)){if(!File.Exists(Path.Combine(target,"INSTALL_COMPLETE.json")))throw new IOException("Эта версия установлена не полностью. Сведения: "+target);File.WriteAllText(Path.Combine(target,"cuda-device.json"),new JavaScriptSerializer().Serialize(new{uuid=device.uuid}),Encoding.UTF8);VoiceInstallCore.Shortcut(target);VoiceInstallCore.Register(target,config.version);VoiceInstallCore.Launch(target);Report("Запускаю установленную версию. Возьмите код в окне модуля и подключите голос в Nexus.",100);return;}
   long extraDownloads=config.archives.Sum(a=>File.Exists(Path.Combine(cache,a.sha256+".zip"))?0:a.bytes),needed=config.archives.Sum(a=>a.unpackedBytes)+extraDownloads+2L*1024*1024*1024;
   if(new DriveInfo(Path.GetPathRoot(home)).AvailableFreeSpace<needed)throw new IOException("Недостаточно места. Для загрузки и установки свободно нужно не менее "+(needed/1073741824d).ToString("0.0")+" ГБ.");
   long total=config.archives.Sum(a=>a.bytes),completed=0;foreach(var a in config.archives){var current=a;long previous=completed;Report("Загружаю "+(a.file=="model.zip"?"модель":"среду")+". "+gpu,0);await VoiceInstallCore.Download(a,Path.Combine(cache,a.sha256+".zip"),bytes=>Report("Загрузка "+((previous+bytes)/1073741824d).ToString("0.00")+" / "+(total/1073741824d).ToString("0.00")+" ГБ",(int)(70*(previous+bytes)/total)),cancellation.Token);completed+=a.bytes;}
   staging=Path.Combine(versions,".installing-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);long unpacked=0,all=config.archives.Sum(a=>a.unpackedBytes);
   foreach(var a in config.archives){cancellation.Token.ThrowIfCancellationRequested();long previous=unpacked;await Task.Run(()=>VoiceInstallCore.Extract(Path.Combine(cache,a.sha256+".zip"),staging,a.unpackedBytes,n=>Report("Распаковываю и проверяю файлы…",70+(int)(25*(previous+n)/all)),a.file=="application.zip",cancellation.Token));unpacked+=a.unpackedBytes;}cancellation.Token.ThrowIfCancellationRequested();
   File.WriteAllText(Path.Combine(staging,"cuda-device.json"),new JavaScriptSerializer().Serialize(new{uuid=device.uuid}),Encoding.UTF8);
   File.WriteAllText(Path.Combine(staging,"INSTALL_COMPLETE.json"),new JavaScriptSerializer().Serialize(new{version=config.version,installedAt=DateTime.UtcNow.ToString("o"),archives=config.archives.Select(a=>a.sha256).ToArray()}),Encoding.UTF8);Directory.Move(staging,target);staging=null;committed=true;cancel.Text="Закрыть";VoiceInstallCore.Shortcut(target);VoiceInstallCore.Register(target,config.version);foreach(var a in config.archives)File.Delete(Path.Combine(cache,a.sha256+".zip"));VoiceInstallCore.Launch(target);
   Report("Подготавливаю голос. Первый запуск может занять до трёх минут; это окно уже можно закрыть.",96);bool ready=false;using(var client=new HttpClient()){client.Timeout=TimeSpan.FromSeconds(2);for(int n=0;n<90;n++){try{var text=await client.GetStringAsync("http://127.0.0.1:18791/status");var result=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(text);if(result.ContainsKey("ready")&&(bool)result["ready"]&&result.ContainsKey("build")&&(string)result["build"]==config.version){ready=true;break;}}catch{}await Task.Delay(2000);}}
   Report(ready?"Голос готов. В Nexus: помощник → настройки → голос → введите код из окна модуля. Ярлык добавлен в меню «Пуск». Когда модуль запущен, интернет для голоса не нужен.":"Файлы установлены, голос ещё подготавливается. Откройте «Голос Уют-7 Qwen TTS» в меню «Пуск» и дождитесь надписи «Голос готов».",100);
  }catch(OperationCanceledException){Report("Остановлено. Незавершённая загрузка сохранена и продолжится при повторной установке.",0);}catch(Exception error){Report(error.Message,0);}finally{busy=false;install.Enabled=true;cancel.Text="Закрыть";cancellation.Dispose();if(staging!=null){try{VoiceInstallCore.RemoveStaging(staging);}catch{Report(status.Text+"\r\nНезавершённая распаковка: "+staging,progress.Value);}}}
 }
}
public static class VoiceSetupProgram {
 [STAThread]public static void Main(string[] args){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;
  if(args.Length==2&&args[0]=="--diagnose"){try{string gpu=VoiceInstallCore.Gpu();File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(new{status="HARDWARE_PREFLIGHT_PASS",gpu=gpu,globalInstallations=0,modelDownloads=0}));}catch(Exception e){File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(new{status="HARDWARE_PREFLIGHT_FAIL",message=e.Message}));}return;}
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{Application.Run(new VoiceSetupForm(VoiceInstallCore.Config()));}catch(Exception e){MessageBox.Show(e.Message,"Установка голоса Nexus",MessageBoxButtons.OK,MessageBoxIcon.Error);}
 }
